def calculate_discounted_total(items: list[Item], discount_pct: float) -> Result[float, ValidationError]:
    if not 0.0 <= discount_pct <= 1.0:
        return Err(ValidationError('Discount must be in 0..1'))
    subtotal = sum(i.unit_price * i.qty for i in items)
    return Ok(round(subtotal * (1.0 - discount_pct), 2))
